    def apply_site_template(self, **kwargs):
        """
        Apply the assigned site templates to the SBTS plan

         @param kwargs:
            plan_name string, Specifies a plan name
            verbose: bool, If True, returns a detailed output from executed operation
            ignore_errors: boo, If True, shows warnings instead of raising errors when operation fails
            timeout: int, Timeout for executing operation
            alias: string, Netact instance name. Default value is 'default'.

        @return: ssh Command Output

        @raise
            From SSH library : SSHException
        """
        plan_name = kwargs.pop('plan_name', 'iv_fw_plan')
        # ops_file = kwargs.pop('ops_file', '$ETCROOT/rac/conf/opdefs/ops/operations/rebuild.xml')
        ignore_errors = kwargs.pop('ignore_errors', False)
        alias = kwargs.pop('alias', 'default')
        verbose = kwargs.pop('verbose ', True)
        timeout = kwargs.pop('timeout', 7200)
        # self.netact_factory.wkflw_engine.apply_site_template(plan_name=plan_name, ops_file=ops_file,
        #                                                     ignore_errors=ignore_errors, alias=alias, timeout=timeout)
        self.netact_factory.netact.apply_site_templates(plan_name=plan_name, verbose=verbose,
                                                        ignore_errors=ignore_errors, timeout=timeout, alias=alias)

    def _add_child(self, base_parent, child):
        copied = deepcopy(child)
        base_parent.append(copied)

    def _update_tag_attr_and_value(self, base_elem, delta_elem):
        base_class_attr = base_elem.attrib
        for attr in delta_elem.attrib:
            # check if all attributes of a delta moc are present in base xml moc and have same value
            # if attribute is not present, add it
            if attr not in base_class_attr:
                base_elem.attrib[attr] = delta_elem.attrib[attr]
            # if value is not same, update it
            elif base_elem.attrib[attr] != delta_elem.attrib[attr]:
                base_elem.attrib[attr] = delta_elem.attrib[attr]

    def _get_delta_file_full_path(self, delta_file, alias):
        delta_dir = get_config_variable(['delta_files'])
        bts_id, delta_dir = self._get_config_files_from_corresponding_bts_dir(
            delta_dir, alias)
        return os.path.join(delta_dir, delta_file)

    def _get_config_files_from_corresponding_bts_dir(self, bts_config_file_path, alias):
        """
            This function returns bts config files like scf_file and delta_file
            etc. from the config directory of the primary bts or chain bts
        """
        # logger.debug("obtaining scf full path...")
        chained = global_vars.alias_chained_dict.get(alias)
        dut = global_vars.alias_dut_dict.get(alias)
        bts_id = get_config_variable(['bts_id'])

        if chained:
            chained_bts_id = get_config_variable([dut, 'bts_id'])
            # scf_dir = _get_config_variable(['chained_bts_scf_dir']).format(
            #     chained=bts_id)
            bts_config_file_path = bts_config_file_path.replace('/{}/'.format(
                bts_id), '/{}/'.format(chained_bts_id))
            bts_id = chained_bts_id
        return bts_id, bts_config_file_path

    def _get_btsid_and_scf_dir(self, alias):
        chained = global_vars.alias_chained_dict.get(alias)
        dut = global_vars.alias_dut_dict.get(alias)
        if chained:
            bts_id = get_config_variable([dut, 'bts_id'])
            scf_dir = get_config_variable(['chained_bts_scf_dir']).format(chained=bts_id)
        else:
            bts_id = get_config_variable(['bts_id'])
            scf_dir = get_config_variable(['scfc_path'])
        logger.debug("btsid :: {0}\tscf_dir :: {1}".format(bts_id, scf_dir))
        return bts_id, scf_dir

    def direct_integration_plan_with_unified_pnp(self, **kwargs):
        """
        *KW*:
        Direct Integration Plan With Unified Pnp
        """

        try:
            base_scf = kwargs["base_scf"]
            delta_scf = kwargs["delta_scf"]
            alias = kwargs.pop('alias', 'default')

            bts_id, scf_dir = self._get_btsid_and_scf_dir(alias)
            base_scf_file = os.path.join(scf_dir, base_scf)
            delta_scf_file = self._get_delta_file_full_path(delta_file=delta_scf, alias=alias)
            xml_parse = lxml_parse()
            base_xml = xml_parse.get_parsed_xml_object(base_scf_file)
            delta_xml = xml_parse.get_parsed_xml_object(delta_scf_file)
            b_namespace = xml_parse.get_namespace(base_xml)
            d_namespace = xml_parse.get_namespace(delta_xml)
            if b_namespace:
                xml_parse.remove_namespace(base_xml, b_namespace)

            if d_namespace:
                xml_parse.remove_namespace(delta_xml, d_namespace)

            # list of all mocs in delta xml file
            all_delta_moc = delta_xml.xpath("//managedObject")
            # all_delta_moc_class_list = [moc.attrib["class"] for moc in all_delta_moc]
            # list of all mocs in base xml file
            all_base_moc = base_xml.xpath("//managedObject")
            # list of all base xml file's moc's classes. makes it easy to compare classes in for loop
            all_base_moc_class_list = [moc.attrib["class"] for moc in all_base_moc]

            for moc in all_delta_moc:
                # check if a moc in delta xml is already present in base xml
                if moc.attrib["class"] in all_base_moc_class_list:

                    delta_class_with_moc = delta_xml.xpath("//managedObject[@class='{}']".format(moc.attrib["class"]))[
                        0]
                    base_class_with_moc = base_xml.xpath("//managedObject[@class='{}']".format(moc.attrib["class"]))[0]

                    # check if all attributes of a delta moc are present in base xml moc and have same value
                    self._update_tag_attr_and_value(base_class_with_moc, moc)

                    # Check if all the children of a delta xml moc are present in the same base xml moc
                    # list of base moc's children for easy looping
                    base_moc_children_list = [v for child in base_class_with_moc for k, v in child.items()]

                    for child in delta_class_with_moc:

                        # if delta xml's moc's child is not in base xml's moc

                        if child.attrib['name'] in base_moc_children_list:

                            # check if all the children have the same value
                            base_child_attr = \
                                base_class_with_moc.xpath("//{0}[@name='{1}']".format(child.tag, child.attrib['name']))[
                                    0]
                            self._update_tag_attr_and_value(base_child_attr, child)

                            # check if delta xml's child's text is same as base xml's or not.
                            # if they are different, modify the base xml's element's text value
                            x_path_str = "//{0}[@name='{1}']".format(child.tag, child.attrib['name'])
                            if child.text != base_class_with_moc.xpath(x_path_str)[0].text:
                                base_class_with_moc.xpath(x_path_str)[0].text = child.text

                            # if delta xml's moc's child is not in base xml's moc, add it
                        else:
                            self._add_child(base_class_with_moc, child)

                # if a moc present in delta xml is not present in base xml, add it
                else:
                    self._add_child(base_xml.xpath("//cmData")[0], moc)

            # change all <managedObject> change to <managedObject operation="create">

            for mo in base_xml.xpath("//managedObject"):
                mo.attrib['operation'] = "create"

            # change cmData type to plan
            base_xml.xpath("//cmData")[0].attrib['type'] = 'plan'
            # the existing base_scf file is changed
            dest_file = base_scf
            # 'execution_logs/{}_modified_{}'.format(get_config_variable(["bts_id"]), base_scf)
            with open(dest_file, 'wb') as f:
                etree.indent(base_xml, space="  ")
                f.write(etree.tostring(base_xml, pretty_print=True, xml_declaration=True, encoding="utf-8"))

        except Exception as xml_e:
            raise PnpXMLParsingFailed(
                'Modifying pnp xml failed because: {0}\n{1}\n{2}'.format(str(xml_e), xml_e.__str__, xml_e.__doc__))

        return dest_file

