    def prepare_unified_pnp_coam_site(self, **kwargs):
        """

        This operation: 1. Creates BTSs site plan 2. Applies site template to the plan 3. Validates the plan
        4. Sends identification parameters to AC Service.

        @param kwargs:
            plan_name: string, Specifies a plan name
            input_file: string, Specifies either full path to plan or name of a plan inside
            file_format: string, Indicates the CSV or RAML2 file format with COAM BTS planned configuration. Defaults to RAML2
            profiler_file: string, Profile file is required in case the CSV format is chosen. Defaults to /var/opt/oss/global/racops/import/
            activate_site_template: bool, Specifies if Site Template is used in planning operation. Defaults to True
            ui_values: bool, Specifies if parameter values are given as UI values in an imported file with COAM BTS planned configuration. If this parameter is not defined,
            internal values are used. Defaults to False
            gps_identification_used: bool, Enable to using GPS based identification. Site object must to be assigned. Defaults to False
            gps_tolerance: int, Defines the allowed deviation (meter) between the reported GPS location of the NE and the location defined int Site object.
            Range: 1..5000. No default value
            maintenance_region_dn: string, Defines DN of the Maintenance Region to be assigned to the NEs that do not have it specified in an
            imported file with planned configuration. An example of a valid format is MRC-1/MR-NE3S. No default value
            verbose: bool, If True, returns a detailed output from executed operation
            ignore_errors: boo, If True, shows warnings instead of raising errors when operation fails
            timeout: int, Timeout for executing operation
            alias: string, Netact instance name. Default value is 'default'.

        """
        plan_name = kwargs.pop('plan_name')
        input_file = kwargs.pop('input_file')
        file_format = kwargs.pop('file_format','RAML2')
        profiler_file = kwargs.pop('profiler_file','/var/opt/oss/global/racops/import/')
        activate_site_template = kwargs.pop('activate_site_template', True)
        ui_values = kwargs.pop('ui_values', False)
        gps_identification_used = kwargs.pop('gps_identification_used', False)
        gps_tolerance = kwargs.pop('gps_tolerance', None)
        maintenance_region_dn = kwargs.pop('maintenance_region_dn', None)
        distribution = kwargs.pop('distribution', None)
        ignore_errors = kwargs.pop('ignore_errors', False)
        alias = kwargs.pop('alias', 'default')
        verbose = kwargs.pop('verbose ', True)
        timeout = kwargs.pop('timeout', 600)

        return self.netact_factory.netact.prepare_unified_pnp_coam_site(plan_name=plan_name, input_file=input_file, file_format=file_format,
                                                                  profiler_file=profiler_file,
                                                                  activate_site_template=activate_site_template, ui_values=ui_values,
                                                                  gps_identification_used=gps_identification_used, gps_tolerance=gps_tolerance,
                                                                  maintenance_region_dn=maintenance_region_dn, verbose=verbose, ignore_errors=ignore_errors,
                                                                  timeout=timeout, alias=alias, distribution=distribution)

    def deintegrate_cloud(self, **kwargs):
        """
        Integrate network elements defined in a given plan.

        This operation will process all managed objects in the plan and trigger NE-NOM integration sequences for all of
        them in parallel. Supported are only managed object classes from com.nokia.nms.integration adaptation. All other
        objects will be ignored.
        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param bool reintegrate: If set to true, Reintegrate in case the NE is already integrated to NOM.
        :param int timeout: Time to wait for the response of the current operation

        :return: list(dict)
        :rtype: list
        """
        cloud_id = kwargs.get("cloud_id", None)
        root_id = kwargs.get("root_id", 'PLMN')
        force_deintegrate = kwargs.get("force_deintegrate", False)
        delete_related_cnfs = kwargs.get("delete_related_cnfs", True)
        cloud_id = kwargs.get("cloud_id", None)
        alias = kwargs.get("alias", None)
        cloud_dn = kwargs.get("cloud_dn", None)
        return self.netact_factory.netact.deintegrate_cloud(cloud_id=cloud_id, root_id=root_id, force_deintegrate=force_deintegrate,
                                               delete_related_cnfs=delete_related_cnfs, ignore_errors=False, timeout=7200,
                                               alias=alias, cloud_dn=cloud_dn)

    def integrate_cloud(self, **kwargs):
        """
        Integrate network elements defined in a given plan.

        This operation will process all managed objects in the plan and trigger NE-NOM integration sequences for all of
        them in parallel. Supported are only managed object classes from com.nokia.nms.integration adaptation. All other
        objects will be ignored.
        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param bool reintegrate: If set to true, Reintegrate in case the NE is already integrated to NOM.
        :param int timeout: Time to wait for the response of the current operation

        :return: list(dict)
        :rtype: list
        """
        cloud_id = kwargs.get("cloud_id", None)
        parameters = kwargs.get("parameters", None)
        cloud_id = kwargs.get("cloud_id", None)
        alias = kwargs.get("alias", None)
        cloud_dn = kwargs.get("cloud_dn", None)
        input_file = kwargs.get("input_file", None)
        file_format = kwargs.get("file_format", 'RAML2')
        overwrite = kwargs.get("overwrite", False)
        if isinstance(parameters, str):
            parameters = json.loads(parameters)
        import_out = self.netact_factory.netact.import_ssd(input_file=input_file, file_format=file_format, overwrite=overwrite, alias=alias)
        logger.debug("Import SSD output: {}".format(import_out))

        return self.netact_factory.netact.integrate_cloud(cloud_id=cloud_id, ignore_errors=False, timeout=7200,
                                               alias=alias, cloud_dn=cloud_dn, parameters=parameters)

