    def check_cnf_sw_compatibility(self, **kwargs):
        """
        The operation ensures that all relevant components of Cloud BTS (vCU, vDU, FHGW, RU, CLOUD) will be compatible with
        each other after upgrade. Release compatibility rules are defined in the target software package
        :param str|list(str) dist_names: Specifies the scope of the operation.
        :param str cnf_sw_id: Specifies the target version of the CNF software imported in Software Manager
        :param int timeout: Time to wait for the response of the current operation

        :return: list(dict)
        :rtype: list
        """
        dist_names = kwargs.get("dist_names", None)
        cnf_sw_id = kwargs.get("cnf_sw_id", None)
        verbose = kwargs.get("verbose", True)
        timeout = kwargs.get("timeout", 3600)
        alias = kwargs.get("alias", None)
        verbose = kwargs.get("verbose", None)
        ignore_errors = kwargs.get("ignore_errors", False)
        return self.netact_factory.netact.check_cnf_sw_compatibility(dist_names=dist_names, cnf_sw_id=cnf_sw_id,
                                                                     verbose=verbose, ignore_errors=ignore_errors, timeout=timeout,
                                                                     alias=alias)

    def check_cnf(self, **kwargs):
        """
        The operation executes a pre-defined set of helm tests which allow to check certain criteria of a CNF
        instance prior to starting the CNF Upgrade (pre-check) or after CNF Upgrade is complete (post-check).
        :param str|list(str) dist_names: Specifies the scope of the operation.
        :param str check_type: Type of CNF check to be executed. Allowed values: preUpgrade or postUpgrade.
        :param int timeout: Time to wait for the response of the current operation

        :return: operation output
        """
        dist_names = kwargs.get("dist_names", None)
        check_type = kwargs.get("check_type", None)
        verbose = kwargs.get("verbose", True)
        timeout = kwargs.get("timeout", 3600)
        alias = kwargs.get("alias", None)
        verbose = kwargs.get("verbose", None)
        ignore_errors = kwargs.get("ignore_errors", False)
        return self.netact_factory.netact.check_cnf(dist_names=dist_names, check_type=check_type,
                                                    verbose=verbose, ignore_errors=ignore_errors,
                                                    timeout=timeout, alias=alias)

    def create_cnf_upgrade_plan(self, **kwargs):
        """
        Creates a CNF software upgrade plan for multiple CNF instances using information
        from both actual configuration and user-provided information (software version).
        :param str|list(str) dist_names: Specifies the scope of the operation.
        :param str cnf_sw_id: Specifies the target version of the CNF software imported in Software Manager
        :param int timeout: Time to wait for the response of the current operation
        """
        plan_name = kwargs.get("plan_name", None)
        dist_names = kwargs.get("dist_names", None)
        cnf_sw_id = kwargs.get("cnf_sw_id", None)
        verbose = kwargs.get("verbose", True)
        timeout = kwargs.get("timeout", 3600)
        alias = kwargs.get("alias", None)
        verbose = kwargs.get("verbose", None)
        ignore_errors = kwargs.get("ignore_errors", False)
        return self.netact_factory.netact.create_cnf_upgrade_plan(plan_name=plan_name, dist_names=dist_names, cnf_sw_id=cnf_sw_id,
                                                                  verbose=verbose, ignore_errors=ignore_errors, timeout=timeout,
                                                                  alias=alias)